use App\Services\HistorialPacienteService;
$base='/pacientes/'.(int)$paciente['id'].'/historial-citas';
?>
<section class="page-heading"><p class="eyebrow"><?= e($paciente['codigo']) ?> · CU20</p><h1>Eventos administrativos</h1><p class="lead"><?= e($paciente['nombres'].' '.$paciente['apellidos']) ?> · <?= e($cita['codigo']) ?></p></section>
<section class="panel historial-panel"><p>Horario vigente: <?= e($cita['inicio_local'].' → '.$cita['fin_local']) ?> · <?= e(Cita::ESTADOS[$cita['estado']]) ?>. Fechas en America/La_Paz.</p><p>Esta consulta no modifica la cita y no contiene información de historia clínica.</p><div class="historial-accesos"><a class="button button-secondary" href="<?= e($base) ?>">Volver al historial</a><a class="text-link" href="/citas/<?= (int)$cita['id'] ?>">Ver detalle CU14</a></div></section>
