<?php endif; ?><nav class="pagination" aria-label="Páginas de eventos"><?php if($eventos['pagina']>1): ?><a class="text-link" data-eventos-anterior href="?pagina=<?= $eventos['pagina']-1 ?>">← Anteriores</a><?php endif; ?><span><?= $eventos['total'] ?> eventos · Página <?= $eventos['pagina'] ?> de <?= $eventos['paginas'] ?></span><?php if($eventos['pagina']<$eventos['paginas']): ?><a class="text-link" data-eventos-siguiente href="?pagina=<?= $eventos['pagina']+1 ?>">Siguientes →</a><?php endif; ?></nav>
